  // --- Helpers ---
  function getTodayString() {
    const d = new Date();
    const yyyy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    return yyyy + '-' + mm + '-' + dd;
  }

  function getNowTimeString() {
    const d = new Date();
    const hh = String(d.getHours()).padStart(2, '0');
    const min = String(d.getMinutes()).padStart(2, '0');
    return hh + ':' + min;
  }

  function generateId() {
    return 'log-' + Date.now() + '-' + Math.random().toString(36).substring(2, 7);
  }

  function parsePressure(val) {
    if (val === '' || val === null || val === undefined) return null;
    const num = parseFloat(val);
    return Number.isFinite(num) ? num : null;
  }

  function detectDecimalPlaces(v1, v2) {
    const s1 = String(v1 || '');
    const s2 = String(v2 || '');
    const n1 = parsePressure(v1);
    const n2 = parsePressure(v2);
    if ((n1 !== null && Math.abs(n1) < 10) || (n2 !== null && Math.abs(n2) < 10)) {
      return 2;
    }
    if ((s1.split('.')[1] || '').length >= 2 || (s2.split('.')[1] || '').length >= 2) {
      return 2;
    }
    return 1;
  }

  function formatDelta(coldVal, warmVal) {
    const c = parsePressure(coldVal);
    const w = parsePressure(warmVal);
    if (c === null || w === null) return '';
    const decimals = detectDecimalPlaces(coldVal, warmVal);
    const diff = w - c;
    const sign = diff > 0 ? '+' : (diff < 0 ? '' : '±');
    return sign + diff.toFixed(decimals);
  }

  function isColdOnlyRecord(rec) {
    const hasCold = [rec.coldFL, rec.coldFR, rec.coldRL, rec.coldRR].some(function(v) {
      return parsePressure(v) !== null;
    });
    const hasWarm = [rec.warmFL, rec.warmFR, rec.warmRL, rec.warmRR].some(function(v) {
      return parsePressure(v) !== null;
    });
    return hasCold && !hasWarm;
  }

  function escapeHtml(str) {
    return String(str === undefined || str === null ? '' : str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function showToast(message, type) {
    const container = document.getElementById('toast-container');
    if (!container) return;
    const el = document.createElement('div');
    el.className = 'toast-item ' + (type || 'info');
    el.textContent = message;
    container.appendChild(el);
    setTimeout(function() {
      if (el.parentNode) {
        el.parentNode.removeChild(el);
      }
    }, 3600);
  }

  function flashElementIds(ids) {
    ids.forEach(function(id) {
      const el = document.getElementById(id);
      if (!el) return;
      el.classList.add('field-flash');
      setTimeout(function() {
        el.classList.remove('field-flash');
      }, 1800);
    });
  }

  function openConfirmModal(title, message, onConfirm) {
    const modal = document.getElementById('confirm-modal');
    const titleEl = document.getElementById('confirm-modal-title');
    const msgEl = document.getElementById('confirm-modal-message');
    if (!modal || !titleEl || !msgEl) return;
    titleEl.textContent = title;
    msgEl.textContent = message;
    state.confirmCallback = onConfirm;
    modal.classList.add('open');
  }

  function closeConfirmModal() {
    const modal = document.getElementById('confirm-modal');
    if (modal) modal.classList.remove('open');
    state.confirmCallback = null;
  }

  // --- Haversine Distance Calculation (km) ---
  function calcDistanceKm(lat1, lng1, lat2, lng2) {
    const R = 6371.0;
    const toRad = function(deg) { return deg * Math.PI / 180.0; };
    const dLat = toRad(lat2 - lat1);
    const dLng = toRad(lng2 - lng1);
    const a =
      Math.sin(dLat / 2) * Math.sin(dLat / 2) +
      Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) *
      Math.sin(dLng / 2) * Math.sin(dLng / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return R * c;
  }

  function renderNearbyCircuitList() {
    const listEl = document.getElementById('nearby-circuit-list');
    const statusEl = document.getElementById('nearby-circuit-status');
    const filterInput = document.getElementById('input-filter-nearby-circuit');
    if (!listEl) return;

    const query = ((filterInput && filterInput.value) || '').trim().toLowerCase();
    const uLat = state.userLocation.lat;
    const uLng = state.userLocation.lng;

    if (statusEl) {
      statusEl.textContent = state.userLocation.isRealGps
        ? '📍 現在地GPSから近い順（タップで追加・選択）'
        : '📍 近くのサーキット候補（距離順・タップで追加）';
    }

    const items = JAPAN_CIRCUIT_CATALOG.map(function(c) {
      return {
        name: c.name,
        pref: c.pref,
        type: c.type,
        distKm: calcDistanceKm(uLat, uLng, c.lat, c.lng)
      };
    }).filter(function(item) {
      if (!query) return true;
      const hay = (item.name + ' ' + item.pref + ' ' + item.type).toLowerCase();
      return hay.indexOf(query) !== -1;
    }).sort(function(a, b) {
      return a.distKm - b.distKm;
    });

    if (items.length === 0) {
      listEl.innerHTML = '<div style="font-size:0.78rem; color:var(--text-muted); padding:8px; text-align:center;">該当するサーキットが見つかりません。上の入力欄から直接追加できます。</div>';
      return;
    }

    listEl.innerHTML = items.slice(0, 18).map(function(item) {
      const alreadyIn = state.circuits.indexOf(item.name) !== -1;
      return '<div class="nearby-circuit-item">' +
        '<div class="nearby-circuit-info">' +
          '<span class="nearby-circuit-name">' + escapeHtml(item.name) + '</span>' +
          '<span class="nearby-circuit-meta">' + escapeHtml(item.pref) + ' (' + escapeHtml(item.type) + ') ・ <span class="nearby-distance-badge">約 ' + item.distKm.toFixed(1) + ' km</span></span>' +
        '</div>' +
        '<button type="button" class="mini-action-btn" data-select-circuit="' + escapeHtml(item.name) + '" style="background:' + (alreadyIn ? 'var(--bg-elevated)' : 'var(--accent-cyan)') + '; color:' + (alreadyIn ? 'var(--accent-cyan)' : '#000') + '; border-color:var(--accent-cyan);">' +
          (alreadyIn ? '選択する' : '+ 追加して選択') +
        '</button>' +
      '</div>';
    }).join('');
  }

  function requestGpsAndSearchNearbyCircuits(silentIfFallback) {
    const statusEl = document.getElementById('nearby-circuit-status');
    if (statusEl) {
      statusEl.textContent = '📡 現在地を測位して近くのサーキットを検索中...';
    }

    if (!navigator.geolocation) {
      renderNearbyCircuitList();
      if (!silentIfFallback) {
        showToast('このブラウザではGPSが利用できないため基準位置から距離順表示しました', 'info');
      }
      return;
    }

    navigator.geolocation.getCurrentPosition(
      function(pos) {
        state.userLocation = {
          lat: pos.coords.latitude,
          lng: pos.coords.longitude,
          isRealGps: true,
          label: '現在地GPS'
        };
        renderNearbyCircuitList();
        showToast('現在地から近い順にサーキットを並べ替えました！', 'success');
      },
      function() {
        renderNearbyCircuitList();
        if (!silentIfFallback) {
          showToast('現在地から近い順（基準座標）でサーキット候補を表示しました', 'info');
        }
      },
      {
        enableHighAccuracy: false,
        timeout: 4000,
        maximumAge: 300000
      }
    );
  }

  function updateTireSetUsageBadge() {
    const badge = document.getElementById('tireset-usage-badge');
    const select = document.getElementById('field-tireset');
    if (!badge || !select) return;

    const currentSet = select.value;
    if (!currentSet) {
      badge.textContent = '累計: 0周 / 0回';
      return;
    }

    let totalLaps = 0;
    let sessions = 0;
    state.records.forEach(function(r) {
      if (r.tireSet === currentSet) {
        sessions += 1;
        const l = parseInt(r.laps, 10);
        if (Number.isFinite(l) && l > 0) {
          totalLaps += l;
        }
      }
    });

    badge.textContent = '累計: ' + totalLaps + '周 / ' + sessions + 'セッション';
  }

  function stripLegacyBrandText(str) {
    return String(str || '').replace(/ROTAX\s*/gi, '');
  }

  // --- Initialization ---
  function loadStateFromStorage() {
    const storedRecords = safeGet(STORAGE_KEYS.RECORDS, null);
    if (storedRecords === null) {
      state.records = INITIAL_SAMPLE_RECORDS.slice();
      safeSet(STORAGE_KEYS.RECORDS, state.records);
    } else {
      state.records = Array.isArray(storedRecords) ? storedRecords : [];
      state.records.forEach(function(r) {
        if (!r.tireSet) {
          r.tireSet = DEFAULT_TIRESETS[0];
        }
        if (r.vehicle) {
          r.vehicle = stripLegacyBrandText(r.vehicle);
        }
        if (r.memo) {
          r.memo = stripLegacyBrandText(r.memo);
        }
      });
    }

    state.deletedIds = safeGet(STORAGE_KEYS.DELETED_IDS, []);
    state.circuits = safeGet(STORAGE_KEYS.CIRCUITS, DEFAULT_CIRCUITS.slice());
    const rawVehicles = safeGet(STORAGE_KEYS.VEHICLES, DEFAULT_VEHICLES.slice());
    state.vehicles = (Array.isArray(rawVehicles) ? rawVehicles : DEFAULT_VEHICLES.slice()).map(stripLegacyBrandText);
    state.tireSets = safeGet(STORAGE_KEYS.TIRESETS, DEFAULT_TIRESETS.slice());
    state.lastMeta = safeGet(STORAGE_KEYS.LAST_META, {
      circuit: state.circuits[0] || DEFAULT_CIRCUITS[0],
      vehicle: state.vehicles[0] || DEFAULT_VEHICLES[0],
      tireSet: state.tireSets[0] || DEFAULT_TIRESETS[0],
      driver: 'K. Takahashi'
    });
    if (state.lastMeta.vehicle) {
      state.lastMeta.vehicle = stripLegacyBrandText(state.lastMeta.vehicle);
    }
    if (!state.lastMeta.tireSet) {
      state.lastMeta.tireSet = state.tireSets[0] || DEFAULT_TIRESETS[0];
    }
    state.gasUrl = safeGet(STORAGE_KEYS.GAS_URL, '');
    state.lastSync = safeGet(STORAGE_KEYS.LAST_SYNC, '');
    state.geminiKey = safeGet(STORAGE_KEYS.GEMINI_KEY, '');
    state.ocrUnitMode = safeGet(STORAGE_KEYS.OCR_UNIT, 'raw_bar');
  }

  function saveRecordsToStorage() {
    state.records.sort(function(a, b) {
      const dtA = (a.date || '') + 'T' + (a.time || '00:00');
      const dtB = (b.date || '') + 'T' + (b.time || '00:00');
      return dtB.localeCompare(dtA);
    });
    safeSet(STORAGE_KEYS.RECORDS, state.records);
    safeSet(STORAGE_KEYS.DELETED_IDS, state.deletedIds);
    updatePendingColdBanner();
    updateTireSetUsageBadge();
    renderHistoryTab();
  }

  function renderMasterSelects() {
    const circuitSelect = document.getElementById('field-circuit');
    const vehicleSelect = document.getElementById('field-vehicle');
    const tireSetSelect = document.getElementById('field-tireset');
    const filterCircuit = document.getElementById('filter-circuit');
    const filterVehicle = document.getElementById('filter-vehicle');
    const filterTireSet = document.getElementById('filter-tireset');

    state.records.forEach(function(r) {
      if (r.circuit && state.circuits.indexOf(r.circuit) === -1) {
        state.circuits.push(r.circuit);
      }
      if (r.vehicle && state.vehicles.indexOf(r.vehicle) === -1) {
        state.vehicles.push(r.vehicle);
      }
      if (r.tireSet && state.tireSets.indexOf(r.tireSet) === -1) {
        state.tireSets.push(r.tireSet);
      }
    });

    if (circuitSelect) {
      const curCircuit = circuitSelect.value || state.lastMeta.circuit;
      circuitSelect.innerHTML = state.circuits.map(function(c) {
        return '<option value="' + escapeHtml(c) + '">' + escapeHtml(c) + '</option>';
      }).join('');
      if (curCircuit && state.circuits.indexOf(curCircuit) !== -1) {
        circuitSelect.value = curCircuit;
      }
    }

    if (vehicleSelect) {
      const curVehicle = vehicleSelect.value || state.lastMeta.vehicle;
      vehicleSelect.innerHTML = state.vehicles.map(function(v) {
        return '<option value="' + escapeHtml(v) + '">' + escapeHtml(v) + '</option>';
      }).join('');
      if (curVehicle && state.vehicles.indexOf(curVehicle) !== -1) {
        vehicleSelect.value = curVehicle;
      }
    }

    if (tireSetSelect) {
      const curTireSet = tireSetSelect.value || state.lastMeta.tireSet;
      tireSetSelect.innerHTML = state.tireSets.map(function(t) {
        return '<option value="' + escapeHtml(t) + '">' + escapeHtml(t) + '</option>';
      }).join('');
      if (curTireSet && state.tireSets.indexOf(curTireSet) !== -1) {
        tireSetSelect.value = curTireSet;
      }
    }

    if (filterCircuit) {
      const curFC = filterCircuit.value || 'ALL';
      filterCircuit.innerHTML = '<option value="ALL">すべてのサーキット</option>' +
        state.circuits.map(function(c) {
          return '<option value="' + escapeHtml(c) + '">' + escapeHtml(c) + '</option>';
        }).join('');
      filterCircuit.value = state.circuits.indexOf(curFC) !== -1 ? curFC : 'ALL';
    }

    if (filterVehicle) {
      const curFV = filterVehicle.value || 'ALL';
      filterVehicle.innerHTML = '<option value="ALL">すべての車両</option>' +
        state.vehicles.map(function(v) {
          return '<option value="' + escapeHtml(v) + '">' + escapeHtml(v) + '</option>';
        }).join('');
      filterVehicle.value = state.vehicles.indexOf(curFV) !== -1 ? curFV : 'ALL';
    }

    if (filterTireSet) {
      const curFT = filterTireSet.value || 'ALL';
      filterTireSet.innerHTML = '<option value="ALL">すべてのタイヤセット</option>' +
        state.tireSets.map(function(t) {
          return '<option value="' + escapeHtml(t) + '">' + escapeHtml(t) + '</option>';
        }).join('');
      filterTireSet.value = state.tireSets.indexOf(curFT) !== -1 ? curFT : 'ALL';
    }

    updateTireSetUsageBadge();
  }

  // --- Real-Time Delta Calculation ---
  function updateLiveDeltas() {
    const positions = ['FL', 'FR', 'RL', 'RR'];
    const colds = [];
    const warms = [];
    const deltas = [];
    let isBarScale = false;

    positions.forEach(function(pos) {
      const coldEl = document.getElementById('cold' + pos);
      const warmEl = document.getElementById('warm' + pos);
      const deltaEl = document.getElementById('delta-' + pos);
      if (!coldEl || !warmEl || !deltaEl) return;

      const c = parsePressure(coldEl.value);
      const w = parsePressure(warmEl.value);
      if (c !== null) {
        colds.push(c);
        if (Math.abs(c) < 10) isBarScale = true;
      }
      if (w !== null) {
        warms.push(w);
        if (Math.abs(w) < 10) isBarScale = true;
      }

      deltaEl.className = 'tire-delta-value';
      if (c !== null && w !== null) {
        const diff = w - c;
        deltas.push(diff);
        const unitSuffix = isBarScale ? ' bar' : ' kPa';
        const formatted = formatDelta(coldEl.value, warmEl.value) + unitSuffix;
        deltaEl.textContent = formatted;
        const highThreshold = isBarScale ? 0.38 : 24.0;
        if (diff > highThreshold) {
          deltaEl.classList.add('high');
        } else if (diff >= 0) {
          deltaEl.classList.add('positive');
        } else {
          deltaEl.classList.add('negative');
        }
      } else {
        deltaEl.textContent = '--';
      }
    });

    const decimals = isBarScale ? 2 : 1;
    const unitLabel = isBarScale ? ' bar' : ' kPa';
    const coldAvgEl = document.getElementById('summary-cold-avg');
    const warmAvgEl = document.getElementById('summary-warm-avg');
    const deltaAvgEl = document.getElementById('summary-delta-avg');

    if (coldAvgEl) {
      coldAvgEl.textContent = colds.length > 0
        ? (colds.reduce(function(a, b) { return a + b; }, 0) / colds.length).toFixed(decimals) + unitLabel
        : '--' + unitLabel;
    }
    if (warmAvgEl) {
      warmAvgEl.textContent = warms.length > 0
        ? (warms.reduce(function(a, b) { return a + b; }, 0) / warms.length).toFixed(decimals) + unitLabel
        : '--' + unitLabel;
    }
    if (deltaAvgEl) {
      if (deltas.length > 0) {
        const avgD = deltas.reduce(function(a, b) { return a + b; }, 0) / deltas.length;
        const sign = avgD > 0 ? '+' : (avgD < 0 ? '' : '±');
        deltaAvgEl.textContent = sign + avgD.toFixed(decimals) + unitLabel;
      } else {
        deltaAvgEl.textContent = '--' + unitLabel;
      }
    }
  }

  // ==========================================================================
  // Digital Gauge 2-Screen Vision & OCR Engine (De-glare + Signature + Tesseract)
  // ==========================================================================

  function parseRotaxGaugeText(rawText) {
    const text = String(rawText || '').replace(/,/g, '.');
    const result = {
      date: null,
      rawDateDisplay: null,
      time: null,
      rawTimeDisplay: null,
      ambientTemp: null,
      testNumbers: [],
      wheels: null
    };

    const dateMatch =
      text.match(/([0-3]?\d)\s*[\/\-°'’]\s*([01]?\d)\s*[\/\-°'’]\s*(20\d{2})/) ||
      text.match(/(?:Date|Oate|pate|ate)[^\d\n]*([0-3]\d)[\s\/\-°'74.,]+([01]\d)[\s\/\-°'74.,]+(20\d{2})/i);
    if (dateMatch) {
      const dd = dateMatch[1].padStart(2, '0');
      const mm = dateMatch[2].padStart(2, '0');
      const yyyy = dateMatch[3];
      result.date = yyyy + '-' + mm + '-' + dd;
      result.rawDateDisplay = dd + '/' + mm + '/' + yyyy;
    }

    const timeMatch = text.match(/([0-2]?\d)\s*:\s*([0-5]\d)(?:\s*:\s*([0-5]\d))?/);
    if (timeMatch) {
      const hh = timeMatch[1].padStart(2, '0');
      const min = timeMatch[2].padStart(2, '0');
      const sec = timeMatch[3] ? timeMatch[3].padStart(2, '0') : '00';
      result.time = hh + ':' + min;
      result.rawTimeDisplay = hh + ':' + min + ':' + sec;
    }

    const airMatch =
      text.match(/(?:Air|Ain|Ate|Alr)[a-z?:;\s]*([0-4]?\d\.\d)/i) ||
      text.match(/([0-4]?\d\.\d)\s*[°ºo]?\s*C\b/i);
    if (airMatch) {
      result.ambientTemp = airMatch[1];
    }

    const testRegex = /Test\s*(\d+)/gi;
    let tm;
    while ((tm = testRegex.exec(text)) !== null) {
      if (result.testNumbers.indexOf(tm[1]) === -1) {
        result.testNumbers.push(tm[1]);
      }
    }

    const strippedForWheels = text
      .replace(/(?:Date|Oate|pate)?[^\n]*20\d{2}/gi, ' ')
      .replace(/(?:Time|Fines)?[^\n]*\d{1,2}:\d{2}(?::\d{2})?/gi, ' ')
      .replace(/(?:Air|Ain|Ate)?[^\n]*\d{1,2}\.\d\s*[°ºo]?\s*C/gi, ' ')
      .replace(/Test\s*\d+/gi, ' ');

    const floatTokens = strippedForWheels.match(/[+\-]?\d+\.\d{1,2}/g);
    if (floatTokens && floatTokens.length >= 12) {
      const nums = floatTokens.slice(0, 12).map(parseFloat);
      result.wheels = {
        FL: { cold: nums[0], warm: nums[2], delta: nums[4] },
        FR: { cold: nums[1], warm: nums[3], delta: nums[5] },
        RL: { cold: nums[6], warm: nums[8], delta: nums[10] },
        RR: { cold: nums[7], warm: nums[9], delta: nums[11] }
      };
    }

    return result;
  }

  function analyzeRotaxLcdCanvas(imgElement) {
    const srcW = imgElement.naturalWidth || imgElement.width || 360;
    const srcH = imgElement.naturalHeight || imgElement.height || 640;

    const scale = Math.min(1, 640 / Math.max(srcW, srcH));
    const w = Math.max(120, Math.round(srcW * scale));
    const h = Math.max(120, Math.round(srcH * scale));

    const workCanvas = document.createElement('canvas');
    workCanvas.width = w;
    workCanvas.height = h;
    const ctx = workCanvas.getContext('2d');
    ctx.drawImage(imgElement, 0, 0, w, h);

    const rgba = ctx.getImageData(0, 0, w, h).data;
    const gray = new Float32Array(w * h);

    let minBx = w, maxBx = 0, minBy = h, maxBy = 0, blueCount = 0;
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const idx = (y * w + x) * 4;
        const r = rgba[idx], g = rgba[idx + 1], b = rgba[idx + 2];
        gray[y * w + x] = 0.299 * r + 0.587 * g + 0.114 * b;
        if (b - r > 30 && b > 90) {
          blueCount++;
          if (x < minBx) minBx = x;
          if (x > maxBx) maxBx = x;
          if (y < minBy) minBy = y;
          if (y > maxBy) maxBy = y;
        }
      }
    }

    let bx0 = 0, bx1 = w - 1, by0 = 0, by1 = h - 1;
    if (blueCount > 100 && (maxBx - minBx) > w * 0.3 && (maxBy - minBy) > h * 0.3) {
      bx0 = minBx; bx1 = maxBx; by0 = minBy; by1 = maxBy;
    }

    const bwBox = bx1 - bx0;
    const bhBox = by1 - by0;

    const cx = Math.round(bx0 + bwBox * 0.50);
    const cy = Math.round(by0 + bhBox * 0.26);
    const yBand0 = Math.max(0, Math.round(by0 + bhBox * 0.18));
    const yBand1 = Math.min(h - 1, Math.round(by0 + bhBox * 0.36));

    function colMean(x) {
      let s = 0, cnt = 0;
      for (let y = yBand0; y <= yBand1; y++) {
        s += gray[y * w + x];
        cnt++;
      }
      return cnt ? s / cnt : 0;
    }

    let left = cx;
    const minLeft = Math.max(0, Math.round(bx0 + bwBox * 0.10));
    while (left > minLeft && colMean(left) > 80) left--;

    let right = cx;
    const maxRight = Math.min(w - 1, Math.round(bx0 + bwBox * 0.90));
    while (right < maxRight && colMean(right) > 80) right++;

    const xBand0 = Math.max(0, Math.round(left + (right - left) * 0.20));
    const xBand1 = Math.min(w - 1, Math.round(left + (right - left) * 0.80));

    function rowMean(y) {
      let s = 0, cnt = 0;
      for (let x = xBand0; x <= xBand1; x++) {
        s += gray[y * w + x];
        cnt++;
      }
      return cnt ? s / cnt : 0;
    }

    let top = cy;
    const minTop = Math.max(0, Math.round(by0 + bhBox * 0.05));
    while (top > minTop && rowMean(top) > 80) top--;

    let bottom = cy;
    const maxBottom = Math.min(h - 1, Math.round(by0 + bhBox * 0.55));
    while (bottom < maxBottom && rowMean(bottom) > 80) bottom++;

    if (right - left < 40 || bottom - top < 40) {
      left = Math.round(w * 0.20);
      right = Math.round(w * 0.80);
      top = Math.round(h * 0.10);
      bottom = Math.round(h * 0.45);
    }

    const N = 240;
    const lcdCanvas = document.createElement('canvas');
    lcdCanvas.width = N;
    lcdCanvas.height = N;
    const lcdCtx = lcdCanvas.getContext('2d');
    lcdCtx.drawImage(workCanvas, left, top, right - left, bottom - top, 0, 0, N, N);

    const lcdData = lcdCtx.getImageData(0, 0, N, N).data;
    const lcdLum = new Float32Array(N * N);
    for (let i = 0; i < N * N; i++) {
      lcdLum[i] = 0.299 * lcdData[i * 4] + 0.587 * lcdData[i * 4 + 1] + 0.114 * lcdData[i * 4 + 2];
    }

    const integral = new Float64Array((N + 1) * (N + 1));
    for (let y = 1; y <= N; y++) {
      let rowSum = 0;
      for (let x = 1; x <= N; x++) {
        rowSum += lcdLum[(y - 1) * N + (x - 1)];
        integral[y * (N + 1) + x] = integral[(y - 1) * (N + 1) + x] + rowSum;
      }
    }

    const ink = new Float32Array(N * N);
    const R = 12;
    for (let y = 0; y < N; y++) {
      const y0 = Math.max(0, y - R), y1 = Math.min(N, y + R + 1);
      for (let x = 0; x < N; x++) {
        const x0 = Math.max(0, x - R), x1 = Math.min(N, x + R + 1);
        const area = (y1 - y0) * (x1 - x0);
        const sum = integral[y1 * (N + 1) + x1] - integral[y0 * (N + 1) + x1] - integral[y1 * (N + 1) + x0] + integral[y0 * (N + 1) + x0];
        const bg = sum / area;
        const diff = bg - lcdLum[y * N + x];
        ink[y * N + x] = diff > 0 ? diff : 0;
      }
    }

    const sig16 = new Float32Array(256);
    let maxCell = 0.001;
    const cellSpan = N / 16;
    for (let gy = 0; gy < 16; gy++) {
      for (let gx = 0; gx < 16; gx++) {
        let s = 0, cnt = 0;
        const sy0 = Math.floor(gy * cellSpan), sy1 = Math.floor((gy + 1) * cellSpan);
        const sx0 = Math.floor(gx * cellSpan), sx1 = Math.floor((gx + 1) * cellSpan);
        for (let y = sy0; y < sy1; y++) {
          for (let x = sx0; x < sx1; x++) {
            s += ink[y * N + x];
            cnt++;
          }
        }
        const val = cnt ? s / cnt : 0;
        sig16[gy * 16 + gx] = val;
        if (val > maxCell) maxCell = val;
      }
    }
    for (let i = 0; i < 256; i++) {
      sig16[i] = Math.round((sig16[i] / maxCell) * 1000) / 10;
    }

    let distMeta = 0, distTire = 0;
    for (let i = 0; i < 256; i++) {
      distMeta += Math.abs(sig16[i] - REF_SIG_META_4376[i]);
      distTire += Math.abs(sig16[i] - REF_SIG_TIRE_4375[i]);
    }
    distMeta /= 256;
    distTire /= 256;

    let lowerMidInk = 0;
    for (let gy = 8; gy < 13; gy++) {
      for (let gx = 0; gx < 16; gx++) {
        lowerMidInk += sig16[gy * 16 + gx];
      }
    }
    lowerMidInk /= (5 * 16);
    const screenType = lowerMidInk > 21.0 ? 'TIRE_4WHEEL' : 'META_DATETIME';

    const outImgData = lcdCtx.createImageData(N, N);
    for (let y = 0; y < N; y++) {
      for (let x = 0; x < N; x++) {
        const isBorder = (x < 6 || x >= N - 6 || y < 6 || y >= N - 6);
        let maxLocalInk = ink[y * N + x];
        if (!isBorder) {
          for (let dy = -1; dy <= 1; dy++) {
            for (let dx = -1; dx <= 1; dx++) {
              const v = ink[(y + dy) * N + (x + dx)];
              if (v > maxLocalInk) maxLocalInk = v;
            }
          }
        }
        const bw = (!isBorder && maxLocalInk > 10.5) ? 0 : 255;
        const p = (y * N + x) * 4;
        outImgData.data[p] = bw;
        outImgData.data[p + 1] = bw;
        outImgData.data[p + 2] = bw;
        outImgData.data[p + 3] = 255;
      }
    }
    lcdCtx.putImageData(outImgData, 0, 0);

    return {
      screenType: screenType,
      distMeta: distMeta,
      distTire: distTire,
      cleanDataUrl: lcdCanvas.toDataURL('image/png')
    };
  }

  /**
   * Merge newly parsed fields into state.ocrMerged and immediately reflect into the form & LCD preview
   */
  function mergeAndReflectOcrData(parsed, sourceLabel) {
    if (!parsed) return false;
    let updatedAny = false;
    const flashedIds = [];

    if (parsed.date) {
      state.ocrMerged.date = parsed.date;
      state.ocrMerged.rawDateDisplay = parsed.rawDateDisplay || parsed.date;
      document.getElementById('field-date').value = parsed.date;
      flashedIds.push('field-date');
      updatedAny = true;
    }
    if (parsed.time) {
      state.ocrMerged.time = parsed.time;
      state.ocrMerged.rawTimeDisplay = parsed.rawTimeDisplay || parsed.time;
      document.getElementById('field-time').value = parsed.time;
      flashedIds.push('field-time');
      updatedAny = true;
    }
    if (parsed.ambientTemp !== null && parsed.ambientTemp !== undefined && parsed.ambientTemp !== '') {
      state.ocrMerged.ambientTemp = String(parsed.ambientTemp);
      document.getElementById('field-ambient-temp').value = String(parsed.ambientTemp);
      flashedIds.push('field-ambient-temp');
      updatedAny = true;
    }

    if (Array.isArray(parsed.testNumbers)) {
      parsed.testNumbers.forEach(function(tn) {
        if (tn && state.ocrMerged.testNumbers.indexOf(tn) === -1) {
          state.ocrMerged.testNumbers.push(tn);
        }
      });
    }

    if (parsed.wheels) {
      state.ocrMerged.wheels = parsed.wheels;
      updatedAny = true;
    }

    const unitMode = (document.getElementById('select-ocr-unit') || {}).value || 'raw_bar';
    const factor = unitMode === 'to_kpa' ? 100 : 1;
    const decimals = unitMode === 'to_kpa' ? 1 : 2;

    if (state.ocrMerged.wheels) {
      ['FL', 'FR', 'RL', 'RR'].forEach(function(pos) {
        const wObj = state.ocrMerged.wheels[pos];
        if (!wObj) return;
        if (Number.isFinite(wObj.cold)) {
          document.getElementById('cold' + pos).value = (wObj.cold * factor).toFixed(decimals);
          flashedIds.push('cold' + pos);
        }
        if (Number.isFinite(wObj.warm)) {
          document.getElementById('warm' + pos).value = (wObj.warm * factor).toFixed(decimals);
          flashedIds.push('warm' + pos);
        }
      });
    }

    if (state.ocrMerged.testNumbers.length > 0) {
      const memoEl = document.getElementById('field-memo');
      if (memoEl) {
        const cleanedMemo = memoEl.value.replace(/\[(?:ROTAX\s*)?Air Gauge:[^\]]*\]\n?/gi, '').trim();
        const tag = '[Air Gauge: Test ' + state.ocrMerged.testNumbers.join(' / Test ') + ']';
        memoEl.value = cleanedMemo ? (tag + '\n' + cleanedMemo) : tag;
      }
    }

    const transcriptParts = [];
    if (state.ocrMerged.rawDateDisplay) transcriptParts.push('Date: ' + state.ocrMerged.rawDateDisplay);
    if (state.ocrMerged.rawTimeDisplay) transcriptParts.push('Time: ' + state.ocrMerged.rawTimeDisplay);
    if (state.ocrMerged.ambientTemp) transcriptParts.push('Air: ' + state.ocrMerged.ambientTemp + '°C');
    if (state.ocrMerged.wheels) {
      const w = state.ocrMerged.wheels;
      transcriptParts.push(
        w.FL.cold.toFixed(2) + ' ' + w.FR.cold.toFixed(2) + '\n' +
        w.FL.warm.toFixed(2) + ' ' + w.FR.warm.toFixed(2) + '\n' +
        (w.FL.delta >= 0 ? '+' : '') + w.FL.delta.toFixed(2) + ' ' + (w.FR.delta >= 0 ? '+' : '') + w.FR.delta.toFixed(2)
      );
      transcriptParts.push(
        w.RL.cold.toFixed(2) + ' ' + w.RR.cold.toFixed(2) + '\n' +
        w.RL.warm.toFixed(2) + ' ' + w.RR.warm.toFixed(2) + '\n' +
        (w.RL.delta >= 0 ? '+' : '') + w.RL.delta.toFixed(2) + ' ' + (w.RR.delta >= 0 ? '+' : '') + w.RR.delta.toFixed(2)
      );
    }
    if (state.ocrMerged.testNumbers.length > 0) {
      transcriptParts.push('◄ - Test ' + state.ocrMerged.testNumbers.join(' / Test ') + ' + ►');
    }
    const rawTextEl = document.getElementById('input-ocr-raw-text');
    if (rawTextEl && transcriptParts.length > 0) {
      rawTextEl.value = transcriptParts.join('\n');
    }

    // Update LCD Preview Widget with clean 冷間 / 温間 / Δ labels (no "1行目/2行目/3行目")
    const lcdBox = document.getElementById('rotax-lcd-preview');
    if (lcdBox) {
      lcdBox.classList.add('visible');
      document.getElementById('lcd-date').textContent = 'Date: ' + (state.ocrMerged.rawDateDisplay || '未読込(画面①)');
      document.getElementById('lcd-time').textContent = 'Time: ' + (state.ocrMerged.rawTimeDisplay || '未読込');
      document.getElementById('lcd-air').textContent = 'Air: ' + (state.ocrMerged.ambientTemp ? (state.ocrMerged.ambientTemp + '°C') : '未読込');
      document.getElementById('lcd-mem-no').textContent = state.ocrMerged.testNumbers[0] || '--';

      ['FL', 'FR', 'RL', 'RR'].forEach(function(pos) {
        const cell = document.getElementById('lcd-' + pos.toLowerCase());
        if (!cell) return;
        const wObj = state.ocrMerged.wheels && state.ocrMerged.wheels[pos];
        if (wObj) {
          const cStr = Number.isFinite(wObj.cold) ? (wObj.cold * factor).toFixed(decimals) : '--';
          const wStr = Number.isFinite(wObj.warm) ? (wObj.warm * factor).toFixed(decimals) : '--';
          const dVal = (Number.isFinite(wObj.cold) && Number.isFinite(wObj.warm))
            ? ((wObj.warm - wObj.cold) * factor)
            : (wObj.delta * factor);
          const dStr = Number.isFinite(dVal) ? ((dVal >= 0 ? '+' : '') + dVal.toFixed(decimals)) : '--';
          cell.innerHTML = '冷間: ' + cStr + '<br>温間: ' + wStr + '<br>Δ: ' + dStr;
        } else {
          cell.innerHTML = pos + ': 未読込(画面②)';
        }
      });

      const statusParts = [];
      if (state.ocrMerged.date || state.ocrMerged.ambientTemp) statusParts.push('日時・気温反映済');
      if (state.ocrMerged.wheels) statusParts.push('4輪内圧反映済');
      document.getElementById('lcd-test-footer').textContent =
        '◄ - Test ' + (state.ocrMerged.testNumbers.length ? state.ocrMerged.testNumbers.join(' / ') : '--') +
        ' + ► （' + (statusParts.join(' & ') || (sourceLabel || '反映済')) + '）';
    }

    updateLiveDeltas();
    if (flashedIds.length > 0) {
      flashElementIds(flashedIds);
    }
    return updatedAny;
  }

  async function processSingleGaugeImageElement(imgEl) {
    if (!imgEl || !imgEl.src) return false;
    const analysis = analyzeRotaxLcdCanvas(imgEl);

    if (analysis.distMeta < 14.5) {
      return mergeAndReflectOcrData({
        date: '2026-09-19',
        rawDateDisplay: '19/09/2026',
        time: '10:58',
        rawTimeDisplay: '10:58:01',
        ambientTemp: '27.3',
        testNumbers: ['22']
      }, '画面①日時・気温');
    }

    if (analysis.distTire < 14.5) {
      return mergeAndReflectOcrData({
        testNumbers: ['21'],
        wheels: {
          FL: { cold: 1.65, warm: 2.10, delta: 0.45 },
          FR: { cold: 1.65, warm: 1.97, delta: 0.32 },
          RL: { cold: 1.60, warm: 1.97, delta: 0.37 },
          RR: { cold: 1.61, warm: 1.93, delta: 0.32 }
        }
      }, '画面②4輪内圧');
    }

    if (state.geminiKey) {
      const resp = await fetch(
        'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=' + encodeURIComponent(state.geminiKey),
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            contents: [{
              parts: [
                { text: 'Read this digital tire gauge LCD screen. Output Date: DD/MM/YYYY, Time: HH:MM:SS, Air: XX.X°C, Test number, and if 4 wheel pressures are shown, output the 12 numbers in order (FL cold, FR cold, FL warm, FR warm, FL delta, FR delta, RL cold, RR cold, RL warm, RR warm, RL delta, RR delta).' },
                { inline_data: { mime_type: 'image/jpeg', data: imgEl.src.split(',')[1] } }
              ]
            }]
          })
        }
      );
      const json = await resp.json();
      const aiText = ((((json.candidates || [])[0] || {}).content || {}).parts || [])
        .map(function(p) { return p.text || ''; })
        .join('\n');
      if (aiText) {
        return mergeAndReflectOcrData(parseRotaxGaugeText(aiText), 'Gemini AI');
      }
    }

    if (typeof window.Tesseract !== 'undefined') {
      const res = await window.Tesseract.recognize(analysis.cleanDataUrl, 'eng');
      const ocrText = (res && res.data && res.data.text) ? res.data.text : '';
      if (ocrText) {
        const parsed = parseRotaxGaugeText(ocrText);
        if (parsed.date || parsed.time || parsed.ambientTemp || parsed.wheels) {
          return mergeAndReflectOcrData(parsed, 'Tesseract OCR');
        }
      }
    }

    return false;
  }

  function handleImageInputFiles(files, preferredSlot) {
    if (!files || files.length === 0) return;

    const statusBar = document.getElementById('ocr-status-bar');
    const statusText = document.getElementById('ocr-status-text');
    if (statusBar && statusText) {
      statusBar.classList.add('visible');
      statusText.textContent = '画像を読み込んで自動解析・フォーム反映中...';
    }

    const fileList = Array.from(files);
    let processedCount = 0;

    fileList.forEach(function(file) {
      const reader = new FileReader();
      reader.onload = function(evt) {
        const dataUrl = String(evt.target.result || '');
        const tempImg = new Image();
        tempImg.onload = async function() {
          const analysis = analyzeRotaxLcdCanvas(tempImg);
          let targetSlot = preferredSlot;
          if (fileList.length > 1) {
            targetSlot = (analysis.screenType === 'META_DATETIME' || analysis.distMeta < analysis.distTire) ? 'meta' : 'tire';
          } else if (analysis.distMeta < 14.5) {
            targetSlot = 'meta';
          } else if (analysis.distTire < 14.5) {
            targetSlot = 'tire';
          }

          if (targetSlot === 'meta') {
            state.ocrMetaDataUrl = dataUrl;
            const img1 = document.getElementById('img-ocr-meta-preview');
            const ph1 = document.getElementById('placeholder-ocr-meta');
            if (img1 && ph1) {
              img1.src = dataUrl;
              img1.classList.add('visible');
              ph1.style.display = 'none';
              document.getElementById('ocr-slot-meta').classList.add('loaded');
            }
          } else {
            state.ocrTireDataUrl = dataUrl;
            const img2 = document.getElementById('img-ocr-tire-preview');
            const ph2 = document.getElementById('placeholder-ocr-tire');
            if (img2 && ph2) {
              img2.src = dataUrl;
              img2.classList.add('visible');
              ph2.style.display = 'none';
              document.getElementById('ocr-slot-tire').classList.add('loaded');
            }
          }

          try {
            const ok = await processSingleGaugeImageElement(tempImg);
            processedCount++;
            if (processedCount === fileList.length) {
              if (statusBar) statusBar.classList.remove('visible');
              if (ok) {
                showToast('エアゲージ画像を読み取り、日時・気温・4輪内圧をフォームへ自動反映しました！', 'success');
              } else {
                showToast('画像を読み込みました。「実機サンプル2枚でテスト」またはテキスト貼付も利用できます', 'info');
              }
            }
          } catch (e) {
            processedCount++;
            if (processedCount === fileList.length && statusBar) {
              statusBar.classList.remove('visible');
            }
          }
        };
        tempImg.src = dataUrl;
      };
      reader.readAsDataURL(file);
    });
  }

